mapper.select:
SELECT COUNT(*)
FROM shopion.tOrdOrderProd OP
INNER JOIN shopion.tOrdOrder O ON O.OrderNo = OP.OrderNo
WHERE OP.OrderNo = #{orderNo} AND OP.OrderProdNo = #{orderProdNo}
AND OP.ShopCode = #{shopCode}
AND O.ChnlCode = #{chnlCode}

SELECT COUNT(*)
FROM shopion.tOrdOrder O
WHERE O.OrderNo = #{orderNo}
AND O.ChnlCode = #{chnlCode}

    AND EXISTS (SELECT 1 FROM shopion.tOrdOrderProd OP WHERE OP.OrderNo = O.OrderNo AND OP.ShopCode = #{shopCode})

SELECT COUNT(*) FROM shopwizard.tAdjAdjust WHERE AdjustNo = #{adjustNo}
AND ShopCode = #{shopCode}
AND ChnlCode = #{chnlCode}
